import { NextRequest, NextResponse } from "next/server";
import { getPedidoStatusByClientToken } from "@/lib/pedidos";

// Estado de pagamento muda em segundos: nunca deixar CDN/navegador reaproveitar.
const NO_STORE = { "Cache-Control": "no-store" };

// `id` here is the opaque client_token generated by the browser, not the
// sequential database id — see lib/pedidos.ts. This keeps the status route
// unguessable without needing an auth layer on a page with no accounts.
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id: clientToken } = await params;

  const pedido = await getPedidoStatusByClientToken(clientToken);
  if (!pedido) {
    return NextResponse.json({ error: "Pedido não encontrado." }, { status: 404, headers: NO_STORE });
  }

  return NextResponse.json({ status: pedido.status, expiresAt: pedido.expires_at }, { headers: NO_STORE });
}
